(function(){
  var UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
  var kw = String(key || '');
  if (kw === '') return '';
  // 搜索节流：两次搜索至少间隔 2500ms，避免触发站点风控（不主动探测频率）
  var last = 0;
  try { last = Number(String(source.get('mbSearchTs') || '0')) || 0; } catch (e0) {}
  var now = Date.now();
  var wait = 2500 - (now - last);
  if (wait > 0 && wait <= 2500) {
    try { java.sleep(wait); } catch (eS) {
      var t0 = Date.now(); while (Date.now() - t0 < wait) {}
    }
  }
  try { source.put('mbSearchTs', String(Date.now())); } catch (e1) {}

  // ① 搜索首页：取一次性令牌 _t，同时种下 PHPSESSID
  var home = '';
  try {
    home = String(java.ajax('https://www.rrssk.com/00PB.html, ' +
      JSON.stringify({ headers: { 'User-Agent': UA } })));
  } catch (e2) { java.toast('猫扑：搜索页获取失败 ' + e2); return ''; }
  var mt = home.match(/name="_t"\s+value="([a-f0-9]{32})"/);
  if (!mt) { java.toast('猫扑：未取得搜索令牌，请稍后重试'); return ''; }
  var token = mt[1];

  // ② 动态取当日签名脚本 URL（v=日期每日轮换），该请求下发 __snc 凭证 Cookie
  var sm = home.match(/<script src="(\/?\?action=signJs[^"]*)"/);
  var sjUrl = sm ? (sm[1].charAt(0) === '/'
      ? 'https://www.rrssk.com' + sm[1]
      : 'https://www.rrssk.com/' + sm[1])
    : 'https://www.rrssk.com/?action=signJs&v=17-20261106';
  var sj = '';
  try {
    sj = String(java.ajax(sjUrl + ', ' +
      JSON.stringify({ headers: { 'User-Agent': UA } })));
  } catch (e3) { java.log('猫扑 signJs 获取失败，使用默认算法: ' + e3); }

  // ③ ★跨日自适应：花括号配平提取当日签名函数原样 eval
  //    （算法结构每日全变：昨日 FNV 正序+5488轮，今日 DJB2 倒序+1861轮；
  //     写死骨架必然跨日失效，故不抽常量，直接执行站点下发的函数体）
  function enc(x) {
    var s = String(java.encodeURI(x));
    return s.replace(/[!'()*]/g, function (c) {
      return '%' + c.charCodeAt(0).toString(16).toUpperCase();
    });
  }
  function braceSlice(src, from) {
    var i = src.indexOf('{', from), d = 0;
    if (i < 0) return '';
    for (var j = i; j < src.length; j++) {
      if (src.charAt(j) === '{') d++;
      else if (src.charAt(j) === '}') { d--; if (d === 0) return src.substring(from, j + 1); }
    }
    return '';
  }
  function makeSign(js) {
    // 函数名/环境检测变量名每天随机，用结构特征定位
    var fs = js.search(/function\s+_[0-9a-fA-F]+\(s\s*,\s*t\s*,\s*ts\)\s*\{/);
    if (fs < 0) fs = js.search(/function\s+\w+\(s\s*,\s*t\s*,\s*ts\)\s*\{/);
    var body = fs >= 0 ? braceSlice(js, fs) : '';
    var fn = body ? (body.match(/function\s+(\w+)\(/) || [])[1] : '';
    if (!fn) return null;
    // 浏览器环境检测常量：typeof X!=="number"||X!==N 与 if(Y!==1)
    var em = js.match(/typeof\s+(\w+)\s*!==\s*"number"\s*\|\|\s*\w+\s*!==\s*(\d+)/);
    var envName = em ? em[1] : 'mbEnv', envVal = em ? Number(em[2]) : 45;
    var trustName = (js.match(/if\((\w+)\s*!==\s*1\)/) || [])[1] || 'mbTrust';
    var pre = 'var ' + envName + '=' + envVal + ';var ' + trustName + '=1;\n' + body + '\n';
    return function (s, t, ts) {
      return String(eval(pre + fn + '(s,t,ts)'));
    };
  }
  var sign = makeSign(sj);
  if (!sign) { java.toast('猫扑：当日签名算法解析失败，请稍后重试'); return ''; }

  var ts = Math.floor(Date.now() / 1000);
  var sig = sign(enc(kw), token, ts);
  var body = '_t=' + token + '&_ts=' + ts + '&_s=' + sig + '&keyword=' + java.encodeURI(kw);
  var headers = {
    'User-Agent': UA,
    'Content-Type': 'application/x-www-form-urlencoded',
    'Referer': 'https://www.rrssk.com/00PB.html',
    'Origin': 'https://www.rrssk.com',
    'X-Requested-With': 'XMLHttpRequest'
  };
  var opt = { method: 'POST', headers: headers, body: body };
  return 'https://www.rrssk.com/?action=search, ' + JSON.stringify(opt);
})()

