(function(){
  var h = String(result);
  // 分类页有 rankList（随页码变化的真列表）；排行页/首页没有，走 picList
  if (h.indexOf('rankList') < 0) {
    return java.getElements('@css:div.picList li');
  }
  var i = h.indexOf('rankList'), j = h.indexOf('</ul>', i);
  var seg = j > i ? h.slice(i, j) : '';
  var re = /<li>([\s\S]*?)<\/li>/g, m, o = [];
  while ((m = re.exec(seg)) !== null) o.push(m[1]);
  if (!o.length) return o;
  // 自然终止：站点末页/超界页返回同一份内容且页面自身已无「下一页」链接。
  // 不写死页数 —— 站点以后加书会重新出现 next，翻页自动继续。
  var first = o[0].replace(/\s+/g, '').slice(0, 200);
  var key = 'mbExploreLast', prev = '';
  try { prev = String(source.get(key) || ''); } catch (e0) {}
  var hasNext = /class=.next.\s+href=.\/list-\d+-\d+\//.test(h);
  if (prev && prev === first && !hasNext) {
    java.log('猫扑发现: 内容与上页重复且无下一页，自然终止');
    return new Packages.java.util.ArrayList();
  }
  try { source.put(key, first); } catch (e1) {}
  return o;
})()

