(function(){
  var html = String(result);
  var id = '';
  var mi = html.match(/var\s+articleid\s*=\s*"([A-Za-z0-9]+)"/);
  if (mi) id = mi[1];
  if (!id) { var mu = String(baseUrl).match(/\/book\/([A-Za-z0-9]+)(?:-\d+)?(?:-\d+)?\.html/); if (mu) id = mu[1]; }
  if (!id) { java.toast('猫扑：无法识别书籍ID'); return new Packages.java.util.ArrayList(); }

  function push(list, url, name) {
    if (!url || !name) return;
    list.push(JSON.stringify({ chapterUrl: url, chapterName: name }));
  }
  var out = [];

  // ① 第一页：只取「全部阅读」目录块，排除倒序的「最新章节」块
  var anchor = html.indexOf('class="direList font13 chapter_list"');
  var seg = anchor >= 0 ? html.slice(anchor) : '';
  var end = seg.indexOf('</ul>');
  if (end > 0) seg = seg.slice(0, end);
  var reA = /<a\s+href="([^"]+)"\s+title="([^"]*)"[^>]*>[^<]*<\/a>/g, m;
  while ((m = reA.exec(seg)) !== null) push(out, m[1], m[2]);

  // ② 目录分页页数（option value="1..N"）
  var total = 1;
  var reO = /<option\s+value="(\d+)"/g, mo;
  while ((mo = reO.exec(html)) !== null) { var v = Number(mo[1]); if (v > total) total = v; }
  if (total > 60) total = 60;   // 防御上限，防异常页死循环

  // ③ 第 2..N 页：AES-256-CBC 加密 POST /index.php?action=loadChapterPage
  if (total > 1) {
    function b64(bytes) {
      var s = '', ch = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
      for (var i = 0; i < bytes.length; i += 3) {
        var a = 255 & bytes[i], b = i + 1 < bytes.length ? (255 & bytes[i + 1]) : 0,
            c = i + 2 < bytes.length ? (255 & bytes[i + 2]) : 0;
        var n = (a << 16) | (b << 8) | c;
        s += ch.charAt((n >> 18) & 63) + ch.charAt((n >> 12) & 63) +
             (i + 1 < bytes.length ? ch.charAt((n >> 6) & 63) : '=') +
             (i + 2 < bytes.length ? ch.charAt(n & 63) : '=');
      }
      return s;
    }
    function encrypt(plain) {
      var kb = new Packages.java.lang.String('Hi3yccTfyPoxfoexMyZ2ohk0xFgjj1mN').getBytes('UTF-8');
      var ib = new Packages.java.lang.String('2685853201487428').getBytes('UTF-8');
      var pb = new Packages.java.lang.String(plain).getBytes('UTF-8');
      var c = Packages.javax.crypto.Cipher.getInstance('AES/CBC/PKCS5Padding');
      c.init(1, new Packages.javax.crypto.spec.SecretKeySpec(kb, 'AES'),
                new Packages.javax.crypto.spec.IvParameterSpec(ib));
      return b64(c.doFinal(pb));
    }
    var UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
    var hdr = { 'User-Agent': UA,
      'Content-Type': 'application/x-www-form-urlencoded',
      'X-Requested-With': 'XMLHttpRequest',
      'Referer': 'https://www.mopbook.com/book/' + id + '.html',
      'Origin': 'https://www.mopbook.com' };
    for (var p = 2; p <= total; p++) {
      try {
        var body = 'data=' + java.encodeURI(encrypt('{"id":"' + id + '","page":' + p + '}'));
        var resp = String(java.ajax('https://www.mopbook.com/index.php?action=loadChapterPage, ' +
          JSON.stringify({ method: 'POST', headers: hdr, body: body })));
        var obj = JSON.parse(resp);
        if (obj.code !== 0 || !obj.data || !obj.data.length) { java.log('猫扑目录第' + p + '页返回空'); break; }
        for (var q = 0; q < obj.data.length; q++) {
          push(out, obj.data[q].chapterurl, obj.data[q].chaptername);
        }
      } catch (eP) { java.log('猫扑目录第' + p + '页异常: ' + eP); break; }
    }
  }

  // ④ 双版本兼容：必须返回 java.util.ArrayList，每项为 JSON 字符串
  var list = new Packages.java.util.ArrayList();
  for (var j = 0; j < out.length; j++) list.add(out[j]);
  java.log('猫扑目录: ' + out.length + ' 章 / ' + total + ' 页');
  return list;
})()

