const rep = CHARS.split("");
rep[43] = "AV";
var o2 = [];
for (var k2 = 0; k2 < h.length; k2++) {
  var cc = h.charCodeAt(k2);
  o2.push(cc >= 0xE001 && cc <= 0xE101 ? rep[cc - 0xE001] : h.charAt(k2));
}
h = o2.join("");
  // 纯正则从整页 HTML 取正文容器（不调用 setContent，避免污染解析上下文）
  var m = h.match(/<div class="content[^"]*">([\s\S]*?)<\/div>/);
  var main = m ? m[1] : '';
  if (!main) return '';
  main = main
    .replace(/\r/g, '')
    .replace(/<i\s+class="icon[^"]*"\s*><\/i>/g, '')
    .replace(/<p>\s*<\/p>/g, '')
    .replace(/<(?:script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/^\s{2,}/gm, '')
    .split('\n')
    .filter(function (ln) {
      var t = ln.trim();
      if (!t) return false;
      if (/mopbook|猫扑小说|收藏.*访问|请收藏|最新网址|www\.|\.com|本站|记住|笔趣|请记住/.test(t)) return false;
      return true;
    })
    .join('\n');
  return main.trim();
})()

